namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious traditional Italian pizza.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10-12 minutes until crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Creamy and aromatic chicken in a rich tomato-based sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, cumin, and turmeric for at least 1 hour.",
                    "Grill or pan-sear the marinated chicken until charred and cooked through.",
                    "Sauté onion, garlic, and ginger until softened.",
                    "Add tomato sauce and spices, simmer for 15 minutes.",
                    "Stir in heavy cream and add the cooked chicken.",
                    "Simmer for another 10 minutes and serve with basmati rice."
                ],
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings.",
                Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning", "Onion"],
                Steps = [
                    "Brown the ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water, simmer until thickened.",
                    "Warm taco shells in the oven for 2-3 minutes.",
                    "Fill shells with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, and sour cream."
                ],
                Ratings = [4, 4, 3, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Pad Thai", Category = "Asian",
                Description = "A classic Thai stir-fried noodle dish with a sweet-tangy sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Sugar", "Lime"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes, then drain.",
                    "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                    "Stir-fry shrimp until pink, then push to the side and scramble eggs.",
                    "Add noodles and sauce, toss everything together.",
                    "Add bean sprouts and green onions, cook for 1 minute.",
                    "Serve topped with crushed peanuts and lime wedges."
                ],
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 5, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "A rich Roman pasta dish with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet until golden.",
                    "Whisk eggs with grated Pecorino and black pepper.",
                    "Toss hot drained pasta with pancetta and rendered fat.",
                    "Remove from heat, quickly stir in egg mixture to create a creamy sauce.",
                    "Serve immediately with extra cheese and pepper."
                ],
                Ratings = [5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt", "Garlic"],
                Steps = [
                    "Halve and pit the avocados, scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in lime juice, diced onion, cilantro, and minced jalapeño.",
                    "Fold in diced tomato and season with salt.",
                    "Serve immediately with tortilla chips."
                ],
                Ratings = [4, 5, 5]
            },
            new Recipe
            {
                Id = 7, Title = "Miso Ramen", Category = "Asian",
                Description = "Hearty Japanese noodle soup with a rich miso broth.",
                Ingredients = ["Ramen noodles", "Miso paste", "Chicken broth", "Soy sauce", "Soft-boiled egg", "Chashu pork", "Green onions", "Nori", "Sesame oil"],
                Steps = [
                    "Bring chicken broth to a simmer, whisk in miso paste and soy sauce.",
                    "Cook ramen noodles according to package directions.",
                    "Prepare soft-boiled eggs (6.5 minutes in boiling water, then ice bath).",
                    "Slice chashu pork and sear briefly in a hot pan.",
                    "Place noodles in bowls, ladle broth over them.",
                    "Top with halved egg, pork slices, green onions, nori, and a drizzle of sesame oil."
                ],
                Ratings = [5, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Butter Chicken", Category = "Indian",
                Description = "Tender chicken in a velvety, buttery tomato sauce.",
                Ingredients = ["Chicken thighs", "Butter", "Tomato purée", "Heavy cream", "Garam masala", "Cumin", "Fenugreek leaves", "Garlic", "Ginger", "Chili powder"],
                Steps = [
                    "Marinate chicken in yogurt and spices for at least 2 hours.",
                    "Grill or broil chicken until lightly charred.",
                    "Melt butter in a pan, sauté garlic and ginger.",
                    "Add tomato purée, garam masala, cumin, and chili powder; simmer 20 minutes.",
                    "Stir in cream and crushed fenugreek leaves.",
                    "Add chicken pieces, simmer 10 minutes, and serve with naan."
                ],
                Ratings = [5, 4, 5, 5, 4]
            },
        ];
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

