﻿@page "/"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Recipe Community</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 Recipe Community</h1>
    <p class="lead">Discover, share, and rate delicious recipes from around the world.</p>
</div>

<h2 class="mb-3">Browse by Category</h2>

<div class="row">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-3 col-sm-6 mb-4">
            <a href="@($"categories/{category.ToLowerInvariant()}")" class="text-decoration-none">
                <div class="card category-card h-100 text-center p-4">
                    <div class="card-body">
                        <div class="category-icon mb-2">@GetCategoryEmoji(category)</div>
                        <h5 class="card-title">@category</h5>
                        <p class="text-muted">@RecipeService.GetByCategory(category).Count recipes</p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Asian" => "🍜",
        _ => "🍽️"
    };
}

