@page "/categories"
@page "/categories/{CategoryName}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(CategoryName is not null ? $"{CategoryName} Recipes" : "All Categories")</PageTitle>

@if (CategoryName is null)
{
    <h1>All Categories</h1>
    <div class="list-group">
        @foreach (var cat in RecipeService.GetCategories())
        {
            <a href="@($"categories/{cat.ToLowerInvariant()}")" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                @cat
                <span class="badge bg-primary rounded-pill">@RecipeService.GetByCategory(cat).Count</span>
            </a>
        }
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    var recipes = RecipeService.GetByCategory(CategoryName);

    @if (recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                            <div class="mb-2">
                                <span class="stars-display">@GetStars(recipe.AverageRating)</span>
                                <small class="text-muted">(@recipe.Ratings.Count ratings)</small>
                            </div>
                            <a href="@($"recipe/{recipe.Id}")" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string? CategoryName { get; set; }

    private static string GetStars(double rating)
    {
        int full = (int)Math.Floor(rating);
        int empty = 5 - full;
        return new string('★', full) + new string('☆', empty);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <PageTitle>@recipe.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item"><a href="@($"categories/{recipe.Category.ToLowerInvariant()}")">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h3>Instructions</h3>
            <ol class="recipe-steps">
                @foreach (var step in recipe.Steps)
                {
                    <li class="mb-2">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mt-4">
        <div class="card-body">
            <h5>Rate this Recipe</h5>
            <p class="text-muted mb-2">
                Average: @recipe.AverageRating / 5
                (@recipe.Ratings.Count ratings)
            </p>
            <StarRating RecipeId="recipe.Id" />
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating ?? selectedRating) ? "star-filled" : "star-empty")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = null"
              role="button"
              title="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
            @(star <= (hoverRating ?? selectedRating) ? "★" : "☆")
        </span>
    }
    @if (submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public int RecipeId { get; set; }

    private int selectedRating;
    private int? hoverRating;
    private bool submitted;

    private void SubmitRating(int rating)
    {
        selectedRating = rating;
        RecipeService.AddRating(RecipeId, rating);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="model.Category">
            <option value="">-- Select a category --</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Mexican">Mexican</option>
            <option value="Asian">Asian</option>
            <option value="American">American</option>
            <option value="French">French</option>
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Description</label>
        <InputTextArea id="description" class="form-control" @bind-Value="model.Description" rows="2"
                       placeholder="A brief description of your recipe" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" class="form-control" @bind-Value="ingredientsText" rows="5"
                       placeholder="Enter one ingredient per line" />
        <div class="form-text">One ingredient per line.</div>
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" class="form-control" @bind-Value="stepsText" rows="5"
                       placeholder="Enter one step per line" />
        <div class="form-text">One step per line.</div>
    </div>

    <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string ingredientsText = string.Empty;
    private string stepsText = string.Empty;
    private string? successMessage;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(model.Title)
        && !string.IsNullOrWhiteSpace(model.Category)
        && !string.IsNullOrWhiteSpace(ingredientsText)
        && !string.IsNullOrWhiteSpace(stepsText);

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Description = model.Description,
            Ingredients = ParseLines(ingredientsText),
            Steps = ParseLines(stepsText)
        };

        RecipeService.AddRecipe(recipe);

        successMessage = $"\"{recipe.Title}\" has been submitted successfully!";
        model = new();
        ingredientsText = string.Empty;
        stepsText = string.Empty;
    }

    private static List<string> ParseLines(string text) =>
        text.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList();

    private class RecipeFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Category { get; set; } = string.Empty;
        public string Description { get; set; } = string.Empty;
    }
}

